#include <iostream>
#include <limits>
#include <optional>

std::optional<long long> notional_cents(long long quantity, long long price) {
    if (quantity < 0 || price < 0) {
        return std::nullopt;
    }
    const auto maximum = std::numeric_limits<long long>::max();
    if (quantity != 0 && price > maximum / quantity) {
        return std::nullopt;
    }
    return quantity * price;
}

void display(long long quantity, long long price) {
    const auto amount = notional_cents(quantity, price);
    if (amount) {
        std::cout << *amount << '\n';
    } else {
        std::cout << "rejected\n";
    }
}

int main() {
    display(4, 500);
    display(0, 500);
    display(-1, 500);
    display(std::numeric_limits<long long>::max(), 2);
}

#include <cstddef>
#include <iostream>
#include <utility>

bool valid_index(long long index, std::size_t count) {
    return index >= 0 && std::cmp_less(index, count);
}

int main() {
    const std::size_t count = 3;
    std::cout << std::boolalpha;
    for (const long long index : {-1LL, 0LL, 2LL, 3LL}) {
        std::cout << valid_index(index, count) << '\n';
    }
    std::cout << 5 / 2 << '\n';
    std::cout << static_cast<double>(5) / 2 << '\n';
}
